package com.smarthub.plus;
import android.content.Context;import android.graphics.*;import android.widget.ImageView;import java.net.*;import java.util.*;import java.util.concurrent.*;
/** Image identity is provider team ID + URL. Only source-supplied image hosts are accepted. */
final class TeamLogoManager {
 private static final ExecutorService work=Executors.newFixedThreadPool(2);private static final android.util.LruCache<String,Bitmap> images=new android.util.LruCache<String,Bitmap>(4*1024*1024){protected int sizeOf(String key,Bitmap value){return value.getAllocationByteCount();}};
 static void bind(Context context,ImageView view,String id,String address){String key=id+"|"+digest(address);view.setTag(key);view.setImageResource(android.R.drawable.ic_menu_gallery);view.setAlpha(.3f);if(id.isEmpty()||!trusted(address))return;Bitmap saved=images.get(key);if(saved!=null){view.setAlpha(1);view.setImageBitmap(saved);return;}work.execute(()->{try{byte[] bytes=address.startsWith("data:image/")?android.util.Base64.decode(address.substring(address.indexOf(',')+1),android.util.Base64.DEFAULT):ArtworkCache.fetch(context,new URL(address.replaceFirst("^http://img.uefa.com/","https://img.uefa.com/")),4*1024*1024);if(bytes.length>4*1024*1024)return;if(!address.startsWith("data:")&&address.toLowerCase(Locale.ROOT).endsWith(".svg")){String xml=new String(bytes,java.nio.charset.StandardCharsets.UTF_8);if(xml.toUpperCase(Locale.ROOT).contains("<!DOCTYPE")||xml.toUpperCase(Locale.ROOT).contains("<!ENTITY"))return;com.caverock.androidsvg.SVG svg=com.caverock.androidsvg.SVG.getFromString(xml);float ratio=svg.getDocumentAspectRatio();if(!Float.isFinite(ratio)||ratio<=0)ratio=1;int w=ratio>=1?256:Math.max(1,Math.round(256*ratio)),h=ratio>=1?Math.max(1,Math.round(256/ratio)):256;Bitmap bitmap=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);new Canvas(bitmap).drawPicture(svg.renderToPicture(w,h));images.put(key,bitmap);view.post(()->{if(key.equals(view.getTag())){view.setAlpha(1);view.setImageBitmap(bitmap);}});return;}BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<=0||o.outHeight<=0||o.outWidth>10000||o.outHeight>10000)return;o.inSampleSize=1;while(o.outWidth/o.inSampleSize>512||o.outHeight/o.inSampleSize>512)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(b!=null){images.put(key,b);view.post(()->{if(key.equals(view.getTag())){view.setAlpha(1);view.setImageBitmap(b);}});}}catch(Exception unavailable){}});}
 private static String digest(String value){try{return SportsCache.key(value);}catch(Exception e){return "invalid";}}
 static boolean trusted(String address){if(address==null)return false;if(address.length()<1500000&&address.matches("data:image/(?:png|jpeg|webp);base64,[A-Za-z0-9+/=\\r\\n]+"))return true;try{URI u=new URI(address);String h=u.getHost();return ("https".equals(u.getScheme())||"http".equals(u.getScheme())&&"img.uefa.com".equals(h))&&u.getUserInfo()==null&&h!=null&&(h.equals("thesportsdb.com")||h.endsWith(".thesportsdb.com")||h.equals("upload.wikimedia.org")||h.equals("www.openligadb.de")||h.equals("i.imgur.com")||h.equals("img.uefa.com"));}catch(Exception e){return false;}}
}
